import boto3


def stream_completion(payload, config=None):
    config = config or {}
    client = boto3.client("bedrock-runtime", region_name=config.get("region"))
    prompt = payload["text"]
    response = client.converse_stream(
        modelId="amazon.nova-pro-v1:0",
        messages=[{"role": "user", "content": [{"text": prompt}]}],
        inferenceConfig={"temperature": 0.9, "maxTokens": 2048},
    )

    for chunk in response["stream"]:
        if "contentBlockDelta" in chunk and "text" in chunk["contentBlockDelta"]:
            yield {"token": chunk["contentBlockDelta"]["text"]}

import boto3

def get_bedrock_client(region_name="us-east-1"):
    return boto3.client("bedrock-runtime", region_name=region_name)

from typing import Dict, Any

class BedrockRequest:
    def __init__(self, text: str, config: Dict[str, Any] = None):
        self.text = text
        self.config = config if config is not None else {}

class BedrockResponse:
    def __init__(self, text: str):
        self.text = text

import boto3

def check_safety(payload, config=None):
    config = config or {}
    client = boto3.client("comprehend", region_name=config.get("region"))
    response = client.detect_moderation_labels(Text=payload["text"])
    return {"moderation_labels": response["ModerationLabels"]}

import boto3

def translate_text(payload, config=None):
    config = config or {}
    client = boto3.client("translate", region_name=config.get("region"))
    response = client.translate_text(
        Text=payload["text"],
        SourceLanguageCode=payload.get("source_language", "auto"),
        TargetLanguageCode=payload["target_language"],
    )
    return {"translated_text": response["TranslatedText"], "source_language": response["SourceLanguageCode"], "target_language": response["TargetLanguageCode"]}

import boto3

def generate_spoken_brief(payload, config=None):
    config = config or {}
    client = boto3.client("polly", region_name=config.get("region"))
    response = client.synthesize_speech(
        Text=payload["text"],
        OutputFormat="mp3",
        VoiceId=payload.get("voice_id", "Joanna"),
    )
    # The audio stream is a StreamingBody object
    audio_stream = response["AudioStream"].read()
    return {"audio_content": audio_stream}
